    list.forEach(function(m){ h += pickRow(m); });
    if(!list.length) h = '<div style="text-align:center;color:var(--text3);padding:30px;font-size:13px">没有匹配的模块</div>';
    listEl.innerHTML = h;
    // 恢复已选状态（切换 tab/搜索后）
    var cur = {};
    (col._pickSel || modIds).forEach(function(id){ cur[id]=1; });
